{
  "name": "@aleee009/opencode-voice-input",
  "version": "0.6.0",
  "description": "Voice input plugin for OpenCode TUI using local FFmpeg and Whisper transcription.",
  "type": "module",
  "license": "MIT",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "voice",
    "speech-to-text",
    "whisper",
    "ffmpeg",
    "tui"
  ],
  "files": [
    "dist"
  ],
  "exports": {
    "./tui": {
      "import": "./dist/tui.js"
    }
  },
  "engines": {
    "opencode": ">=1.18.0"
  },
  "scripts": {
    "build": "tsup",
    "prepack": "npm run build"
  },
  "peerDependencies": {
    "@opencode-ai/plugin": "*",
    "@opentui/core": ">=0.4.5",
    "@opentui/solid": ">=0.4.5",
    "solid-js": ">=1.9.0"
  },
  "devDependencies": {
    "@opencode-ai/plugin": "^1.18.9",
    "@opentui/core": "^0.4.5",
    "@opentui/solid": "^0.4.5",
    "esbuild-plugin-solid": "^0.6.0",
    "solid-js": "^1.9.14",
    "tsup": "^8.5.1",
    "typescript": "^5.9.0"
  }
}
